    {!ro && <AddRow id="ignore_game" label="Game name" placeholder={t('modules_ignore_game_placeholder')} max={100} busy={busy} k="game_add" btn={t('modules_add_game')} onAdd={async (game) => !!(await act({ action: 'game_add', game }))?.success} />}
    <h4 className="md-h4">{t('modules_currently_ignored_games')}</h4>
