// 6. Ad Notices
const ADMSG: [string, string, string, string][] = [
  ['ad_upcoming_message', 'enable_upcoming_ad_message', 'modules_ad_upcoming_message', 'modules_ad_upcoming_message_placeholder'],
  ['ad_1min_message', 'enable_1min_ad_message', 'modules_ad_1min_message', 'modules_ad_1min_message_placeholder'],
  ['ad_start_message', 'enable_start_ad_message', 'modules_ad_start_message', 'modules_ad_start_message_placeholder'],
  ['ad_end_message', 'enable_end_ad_message', 'modules_ad_end_message', 'modules_ad_end_message_placeholder'],
  ['ad_snoozed_message', 'enable_snoozed_ad_message', 'modules_ad_snoozed_message', 'modules_ad_snoozed_message_placeholder'],
]
function Ads({ c }: { c: Ctx }) {
  const { p, act, busy, ro } = c
  const [v, setV] = useState<Record<string, string>>(() => Object.fromEntries(Object.entries(p.ad || {}).map(([k, x]) => [k, String(x ?? '')])))
  const b = (k: string) => v[k] === '1' || v[k] === 'true'
  const set = (k: string, x: string) => setV((o) => ({ ...o, [k]: x }))
  const flag = (k: string) => (x: boolean) => set(k, x ? '1' : '0')
  const win = v.raid_ad_snooze_window_minutes || '10', winOk = /^\d+$/.test(win) && +win >= 1 && +win <= 30
  const msg = (k: string, en: string, label: string, ph: string, note?: ReactNode) => <div key={k} className="md-msg">
    <Opt id={en} on={b(en)} set={flag(en)} disabled={ro} label={<b>{t(label)}</b>} />
    {note}
    <textarea id={k} aria-label={t(label)} className="input md-ta" rows={3} maxLength={500} placeholder={t(ph)} value={v[k] || ''} disabled={ro} onChange={(e) => set(k, e.target.value)} />
    <Count n={(v[k] || '').length} />
  </div>
  const save = () => act({ action: 'ad_save', ...Object.fromEntries(['ad_upcoming_message', 'ad_1min_message', 'ad_start_message', 'ad_end_message', 'ad_snoozed_message', 'raid_ad_snooze_message'].map((k) => [k, v[k] || ''])),
    ...Object.fromEntries(['enable_ad_notice', 'enable_upcoming_ad_message', 'enable_1min_ad_message', 'enable_start_ad_message', 'enable_end_ad_message', 'enable_snoozed_ad_message', 'enable_ai_ad_breaks', 'enable_raid_ad_snooze', 'enable_raid_ad_snooze_message'].map((k) => [k, b(k) ? '1' : '0'])),
    raid_ad_snooze_window_minutes: win })
  return <>
    <Masonry>
      <Card icon="fas fa-rectangle-ad" title={t('modules_ad_notice_messages_title')}>
        <div className="st-opts">
          <Opt id="enable_ad_notice" on={b('enable_ad_notice')} set={flag('enable_ad_notice')} disabled={ro} label={<b>{t('modules_enable_ad_notice')}</b>} help={t('modules_enable_ad_notice_help')} />
          <Opt id="enable_ai_ad_breaks" on={b('enable_ai_ad_breaks')} set={flag('enable_ai_ad_breaks')} disabled={ro} label={<b>{t('modules_enable_ai_ad_breaks_label')}</b>} badge={<Pill k="pill-accent"><i className="fas fa-crown" /> {t('modules_premium_feature_badge')}</Pill>} help={t('modules_enable_ai_ad_breaks_help')} />
        </div>
        <h4 className="md-h4">{t('modules_advertisement_messages')}</h4>
        {ADMSG.map(([k, en, l, ph]) => msg(k, en, l, ph, k === 'ad_snoozed_message' ? <p className="muted small md-note"><Rich k="modules_ad_snoozed_note" /></p> : undefined))}
      </Card>
      <Card icon="fas fa-people-arrows" title={t('modules_raid_ad_snooze_title')}>
        <p className="muted small"><Rich k="modules_raid_ad_snooze_note" /></p>
        <div className="st-opts"><Opt id="enable_raid_ad_snooze" on={b('enable_raid_ad_snooze')} set={flag('enable_raid_ad_snooze')} disabled={ro} label={<b>{t('modules_enable_raid_ad_snooze')}</b>} help={t('modules_enable_raid_ad_snooze_help')} /></div>
        <Fld id="raid_win" label={t('modules_raid_ad_snooze_window')} help={t('modules_raid_ad_snooze_window_help')}><input id="raid_win" type="number" min={1} max={30} className={`input md-num${winOk ? '' : ' input-err'}`} value={win} disabled={ro} onChange={(e) => set('raid_ad_snooze_window_minutes', e.target.value)} /></Fld>
        {msg('raid_ad_snooze_message', 'enable_raid_ad_snooze_message', 'modules_raid_ad_snooze_message', 'modules_raid_ad_snooze_message_placeholder', undefined)}
        <p className="muted small"><Rich k="modules_raid_ad_snooze_variables_note" /></p>
      </Card>
    </Masonry>
    {!ro && <div className="row-btns md-savebar"><SaveBtn busy={busy} k="ad_save" label={t('modules_save_ad_notice_settings')} disabled={!winOk} onClick={save} /></div>}
  </>
}

// 8. Twitch Chat Alerts
const CHAT: [string, string, string, string, [string, string, string?][]][] = [
  ['general', 'modules_general_events', 'fas fa-heart', 'modules_save_general_events', [['follower_alert', 'modules_follower_alert'], ['cheer_alert', 'modules_cheer_alert'], ['raid_alert', 'modules_raid_alert']]],
  ['subscription', 'modules_subscription_events', 'fas fa-star', 'modules_save_subscription_events', [['subscription_alert', 'modules_subscription_alert'], ['gift_subscription_alert', 'modules_gift_subscription_alert', 'modules_gift_sub_info_tooltip']]],
  ['hype-train', 'modules_hype_train_events', 'fas fa-train', 'modules_save_hype_train_events', [['hype_train_start', 'modules_hype_train_start'], ['hype_train_end', 'modules_hype_train_end']]],
  ['beta', 'modules_beta_features', 'fas fa-arrow-up', 'modules_save_beta_features', [['gift_paid_upgrade', 'modules_gift_paid_upgrade_label'], ['prime_paid_upgrade', 'modules_prime_paid_upgrade_label'], ['pay_it_forward', 'modules_pay_it_forward_label']]],
]
const PH: Record<string, string> = { gift_paid_upgrade: 'Placeholders: (user), (tier)', prime_paid_upgrade: 'Placeholders: (user), (tier)', pay_it_forward: 'Placeholders: (user), (tier), (gifter)' }
function ChatAlerts({ c }: { c: Ctx }) {
  return <Masonry>{CHAT.map((s) => <ChatSec key={s[0]} s={s} c={c} />)}</Masonry>
}
function ChatSec({ s, c }: { s: typeof CHAT[number]; c: Ctx }) {
  const { p, act, busy, ro } = c, [sec, title, icon, save, fields] = s
  const [v, setV] = useState<Record<string, string>>(() => Object.fromEntries(fields.map(([k]) => [k, p.chat_alerts?.[k] ?? p.default_chat_alerts?.[k] ?? ''])))
  return <Card icon={icon} title={t(title)}>
    {sec === 'beta' && <p className="muted small">{t('modules_beta_features_note')}</p>}
    {fields.map(([k, l, tip]) => <Fld key={k} id={`ca-${k}`} label={t(l)} help={tip ? t(tip) : undefined} foot={<Count n={v[k].length} extra={PH[k]} />}>
      <textarea id={`ca-${k}`} className="input" rows={2} maxLength={500} value={v[k]} disabled={ro} onChange={(e) => setV({ ...v, [k]: e.target.value })} /></Fld>)}
    {!ro && <div className="row-btns md-foot"><SaveBtn busy={busy} k={`ca-${sec}`} label={t(save)} onClick={() => act({ action: 'chat_alerts_save', section: sec, values: JSON.stringify(v) }, { key: `ca-${sec}` })} /></div>}
  </Card>
}

// 9. Automated Shoutouts
function Shoutouts({ c }: { c: Ctx }) {
  const { p, act, busy, ro } = c
  const [m, setM] = useState(String(p.shoutouts.cooldown_minutes || 60)), [tr, setTr] = useState(p.shoutouts.tracking || [])
  useEffect(() => setTr(p.shoutouts.tracking || []), [p])
  useEffect(() => { const h = setInterval(() => { if (document.visibilityState === 'visible') get<{ success: boolean; shoutouts: P['shoutouts'] }>(`${API}?part=shoutouts`).then((r) => r.success && setTr(r.shoutouts.tracking || [])).catch(() => {}) }, 15000); return () => clearInterval(h) }, [])
  const ok = /^\d+$/.test(m) && +m >= 60 && +m <= 10080
  const rows = [...tr].sort((a, b) => b.shoutout_time.localeCompare(a.shoutout_time))
  return <>
    <Card icon="fas fa-bullhorn" title={t('modules_automated_shoutouts_title')}><p className="muted">{t('modules_automated_shoutouts_description')}</p>
      <h4 className="md-h4">{t('modules_cooldown_settings')}</h4>
      <div className="md-inline"><Fld id="so_cd" label={t('modules_automated_shoutout_cooldown_label')} help={t('modules_automated_shoutout_cooldown_help')}><input id="so_cd" type="number" min={60} className={`input md-num${ok ? '' : ' input-err'}`} value={m} disabled={ro} onChange={(e) => setM(e.target.value)} /></Fld>
        {!ro && <SaveBtn busy={busy} k="shout_cooldown" label={t('modules_save_cooldown_settings')} disabled={!ok} onClick={() => act({ action: 'shout_cooldown', minutes: m })} />}</div>
    </Card>
    <Card icon="fas fa-hourglass-half" title={t('modules_users_on_cooldown')} right={<Pill k="pill-muted">{rows.length}</Pill>}>
      <p className="muted small">{t('modules_users_on_cooldown_description')}</p>
      {rows.length ? <table className="bp-table tk-table md-table"><thead><tr><th>{t('modules_table_user')}</th><th>{t('modules_table_last_shoutout')}</th><th className="tk-num">{t('modules_table_cooldown_remaining')}</th></tr></thead>
        <tbody>{rows.map((r) => <tr key={r.user_id}><td data-l={t('modules_table_user')}><b>{r.user_name}</b></td><td data-l={t('modules_table_last_shoutout')}>{r.shoutout_time}</td>
          <td data-l={t('modules_table_cooldown_remaining')} className="tk-num">{r.is_expired ? <Pill k="pill-ok">{t('modules_cooldown_ready')}</Pill> : <Pill k="pill-warn">{r.remaining_minutes} {t('modules_cooldown_min')}</Pill>}</td></tr>)}</tbody></table>
        : <Empty>{t('modules_no_users_on_cooldown')}</Empty>}
    </Card>
  </>
}

// 10. TTS
const VOICES = ['Alloy', 'Ash', 'Ballad', 'Coral', 'Echo', 'Fable', 'Nova', 'Onyx', 'Sage', 'Shimmer', 'Verse']
function Tts({ c }: { c: Ctx }) {
  const { p, act, busy, ro } = c
  const [style, setStyle] = useState(p.tts.style === 'expressive' ? 'expressive' : 'normal'), [voice, setVoice] = useState(VOICES.includes(p.tts.voice) ? p.tts.voice : 'Alloy')
  const [ex, setEx] = useState(p.tts.expressive_voice || ''), [vs, setVs] = useState<{ id: string; name: string }[] | null>(null), [def, setDef] = useState('')
  useEffect(() => { get<{ success: boolean; voices: { id: string; name: string }[]; default: string }>(`${API}?voices=1`, 20000).then((r) => { setVs(r.voices || []); setDef(r.default || ''); if (!p.tts.expressive_voice && r.default) setEx(r.default) }).catch(() => setVs([])) }, []) // eslint-disable-line react-hooks/exhaustive-deps
  return <Card icon="fas fa-microphone" title={t('modules_tts_settings_title')}>
    <p className="muted">{t('modules_tts_settings_description')}</p>
    <div className="notice notice-info"><i className="fas fa-circle-info" /> <span><Rich k="modules_tts_help_choosing_voice" /></span></div>
    <h4 className="md-h4">{t('modules_voice_configuration')}</h4>
    <div className="md-two">
      <Fld id="tts_style" label={t('modules_tts_style_label')} help={t('modules_tts_style_help')}><select id="tts_style" className="input" value={style} disabled={ro} onChange={(e) => setStyle(e.target.value)}><option value="normal">{t('modules_tts_style_normal')}</option><option value="expressive">{t('modules_tts_style_expressive')}</option></select></Fld>
      <Fld id="tts_language" label={t('modules_tts_language_label')} help={t('modules_tts_language_help')}><select id="tts_language" className="input" value="en" disabled={ro} onChange={() => {}}><option value="en">{t('modules_tts_language_english')}</option></select></Fld>
      {style === 'normal' ? <Fld id="tts_voice" label={t('modules_tts_voice_label')} help={t('modules_tts_voice_help')}><select id="tts_voice" className="input" value={voice} disabled={ro} onChange={(e) => setVoice(e.target.value)}>{VOICES.map((x) => <option key={x} value={x}>{x}{x === 'Alloy' ? ` ${t('modules_tts_voice_default_suffix')}` : ''}</option>)}</select></Fld>
        : <Fld id="tts_ex" label={t('modules_tts_expressive_voice_label')} help={vs && !vs.length ? t('modules_tts_expressive_voice_empty') : t('modules_tts_expressive_voice_help')}><select id="tts_ex" className="input" value={ex} disabled={ro || !vs?.length} onChange={(e) => setEx(e.target.value)}>
          <option value="">{vs ? t('modules_tts_expressive_voice_placeholder') : 'Loading voices...'}</option>{(vs || []).map((x) => <option key={x.id} value={x.id}>{x.name}{x.id === def ? ` ${t('modules_tts_voice_default_suffix')}` : ''}</option>)}</select></Fld>}
    </div>
    {!ro && <div className="row-btns md-foot"><SaveBtn busy={busy} k="tts_save" label={t('modules_save_tts_settings')} disabled={style === 'expressive' && !ex} onClick={() => act({ action: 'tts_save', voice, language: 'en', style, expressive_voice: ex })} /></div>}
  </Card>
}

// 11. Custom Module Bots
function ModuleBots({ c }: { c: Ctx }) {
  const { p, act, busy, ro, ask } = c
  const [name, setName] = useState(''), [id, setId] = useState('')
  const okName = /^@?[A-Za-z0-9_]{3,25}$/.test(name.trim())
  const bots = [...(p.module_bots || [])].sort((a, b) => Number(b.id) - Number(a.id))
  return <>
    <div className="notice notice-info"><i className="fas fa-circle-info" /> <span><b>{t('modules_module_bot_what_title')}</b> <Rich k="modules_module_bot_what_desc" /></span></div>
    <Masonry>
      <Card icon="fas fa-robot" title={t('modules_add_custom_module_bot')}>
        <p className="muted small">{t('modules_custom_module_bots_description')}</p>
        <Fld id="bot_username" label={t('modules_bot_username_label')} help={t('modules_bot_username_help')}><input id="bot_username" className="input" maxLength={26} placeholder={t('modules_bot_username_placeholder')} value={name} disabled={ro} onChange={(e) => { setName(e.target.value); setId('') }} /></Fld>
        <Fld id="bot_id" label={<>{t('modules_bot_id_label')} <span className="muted small">{t('modules_bot_id_auto_resolved')}</span></>} help={t('modules_bot_id_help')}>
          <div className="md-add"><input id="bot_id" className="input mono" readOnly placeholder={t('modules_bot_id_placeholder')} value={id} />
            {!ro && <SaveBtn busy={busy} k="bot_resolve" cls="btn-ghost" icon="fas fa-magnifying-glass" label={t('modules_resolve_id_btn')} disabled={!okName} onClick={async () => { const r = await act({ action: 'bot_resolve', bot_username: name.trim() }, { quiet: true, reload: false }); if (r?.success && r.id) setId(r.id) }} />}</div></Fld>
        {!ro && <div className="row-btns md-foot"><SaveBtn busy={busy} k="bot_add" icon="fas fa-plus" label={t('modules_add_bot_btn')} disabled={!okName} onClick={async () => { if ((await act({ action: 'bot_add', bot_username: name.trim() }))?.success) { setName(''); setId('') } }} /></div>}
        <div className="notice notice-warn"><i className="fas fa-shield-halved" /> <span><Rich k="modules_verification_required_note" /></span></div>
      </Card>
      <Card icon="fas fa-link" title={t('modules_linked_bots')} right={<Pill k="pill-muted">{bots.length}</Pill>}>
        {bots.length ? <table className="bp-table tk-table md-table"><thead><tr><th>{t('modules_table_bot_username')}</th><th>{t('modules_table_bot_id')}</th><th>{t('modules_table_status')}</th>{!ro && <th className="tk-num">{t('modules_table_actions')}</th>}</tr></thead>
          <tbody>{bots.map((b) => { const v = Number(b.is_verified) === 1; return <tr key={b.id}><td data-l={t('modules_table_bot_username')}><i className="fas fa-robot" /> <b>{b.bot_username}</b></td><td data-l={t('modules_table_bot_id')}><code className="tk-code">{b.bot_channel_id}</code></td>
            <td data-l={t('modules_table_status')}><Pill k={v ? 'pill-ok' : 'pill-warn'}><i className={v ? 'fas fa-check-circle' : 'fas fa-clock'} /> {v ? t('modules_status_verified') : t('modules_status_pending_verification')}</Pill></td>
            {!ro && <td className="tk-num md-acts"><button type="button" className="btn btn-ghost md-x" aria-label={`Remove ${b.bot_username}`} disabled={!!busy} onClick={() => ask({ title: 'Remove module bot?', body: <p>Unlink <b>{b.bot_username}</b> from your channel?</p>, yes: t('protection_remove'), run: () => act({ action: 'bot_remove', record_id: String(b.id) }) })}><i className="fas fa-trash" /></button></td>}</tr> })}</tbody></table>
          : <Empty>{t('modules_no_module_bots_linked')}</Empty>}
      </Card>
    </Masonry>
  </>
}

